program='''from collections import deque

def _variants(shape):
    out=[]
    for flip in range(2):
        for rot in range(4):
            pts=[]
            for r,c in shape:
                x,y=(r,-c if flip else c)
                for _ in range(rot): x,y=y,-x
                pts.append((x,y))
            mr=min(x for x,y in pts); mc=min(y for x,y in pts)
            s=frozenset((x-mr,y-mc) for x,y in pts)
            if s not in [a for a,b in out]: out.append((s,(flip,rot)))
    return out

def transform(grid):
    h,w=len(grid),len(grid[0]); a=[row[:] for row in grid]
    colors={v for row in grid for v in row if v!=1}
    comps=[]
    for color in colors:
        seen=set()
        for r in range(h):
            for c in range(w):
                if grid[r][c]!=color or (r,c) in seen: continue
                q=[(r,c)]; seen.add((r,c)); comp=[]
                while q:
                    x,y=q.pop(); comp.append((x,y))
                    for dx in (-1,0,1):
                        for dy in (-1,0,1):
                            z=(x+dx,y+dy)
                            if 0<=z[0]<h and 0<=z[1]<w and z not in seen and grid[z[0]][z[1]]==color:
                                seen.add(z); q.append(z)
                comps.append((color,comp))
    if not comps:return a
    refcolor,ref=max(comps,key=lambda z:len(z[1]))
    r0=min(r for r,c in ref); c0=min(c for r,c in ref)
    proto={(r-r0,c-c0) for r,c in ref}
    forms=_variants(proto)
    # Keep the reference object as-is. Complete every smaller colored fragment
    # by placing a symmetry of the reference shape over its given cells.
    for color,fraglist in comps:
        if (color,fraglist)==(refcolor,ref): continue
        frag=set(fraglist)
        opts=[]
        for shape,ori in forms:
            for pr,pc in shape:
                for qr,qc in frag:
                    dr,dc=qr-pr,qc-pc
                    placed={(r+dr,c+dc) for r,c in shape}
                    if not frag<=placed: continue
                    if min(r for r,c in placed)<0 or max(r for r,c in placed)>=h or min(c for r,c in placed)<0 or max(c for r,c in placed)>=w: continue
                    sr=sum(r for r,c in placed)/len(placed); sc=sum(c for r,c in placed)/len(placed)
                    fr=sum(r for r,c in frag)/len(frag); fc=sum(c for r,c in frag)/len(frag)
                    score=((sr-fr)**2+(sc-fc)**2, ori[0],ori[1],dr,dc)
                    opts.append((score,placed))
        if opts:
            _,best=min(opts,key=lambda x:x[0])
            for r,c in frag: a[r][c]=1
            for r,c in best: a[r][c]=color
    return a
'''
